t.script:
//
var activeQuestId = '';
var activeQuestName = 'default';
var currentAiMessage = null;
var currentAgentCards = {};
var streaming = false;

document.getElementById('quest-list').addEventListener('click', function(e) {
    var item = e.target.closest('.quest-item');
    if (!item) return;
    document.querySelectorAll('.quest-item').forEach(function(el) { el.classList.remove('active'); });
    item.classList.add('active');
    activeQuestId = item.dataset.id;
    activeQuestName = item.dataset.name;
    document.getElementById('active-quest-name').textContent = item.textContent.trim();
});

document.getElementById('prompt-input').addEventListener('keydown', function(e) {
    if (e.key === 'Enter' && !e.shiftKey) {
        e.preventDefault();
        sendMessage();
    }
});

function _(tag, cls, html) {
    var el = document.createElement(tag);
    if (cls) el.className = cls;
    if (html !== undefined) el.innerHTML = html;
    return el;
}

function scrollBottom() {
    var msgs = document.getElementById('messages');
    msgs.scrollTop = msgs.scrollHeight;
}

function sendMessage() {
    var input = document.getElementById('prompt-input');
    var btn = document.getElementById('send-btn');
    var prompt = input.value.trim();
    if (!prompt || streaming) return;
    input.value = '';
    streaming = true;
    btn.disabled = true;

    var userMsg = _('div', 'message user', escapeHtml(prompt));
    document.getElementById('messages').appendChild(userMsg);
    scrollBottom();

    currentAiMessage = _('div', 'message ai', '');
    document.getElementById('messages').appendChild(currentAiMessage);
    currentAgentCards = {};
    scrollBottom();

    var params = 'prompt=' + encodeURIComponent(prompt);
    if (activeQuestId) params += '&quest_id=' + activeQuestId;

    var es = new EventSource('/ai/stream?' + params);

    es.onmessage = function(e) {
        try {
            var event = JSON.parse(e.data);
            handleStreamEvent(event, es);
        } catch(err) {
            console.error('Parse error:', err);
        }
    };

    es.onerror = function() {
        es.close();
        finishStream();
    };
}

function handleStreamEvent(event, es) {
    switch (event.type) {
        case 'supervisor.start':
            currentAiMessage.innerHTML +=
                '<div style="color:var(--text-muted);margin-bottom:8px">' +
                '🔍 <em>Supervisor: ' + escapeHtml(event.reasoning) + '</em></div>';
            break;
        case 'agent.start':
            currentAgentCards[event.agent_id] = _('div', 'agent-card', '');
            currentAgentCards[event.agent_id].innerHTML =
                '<div class="agent-card-header" onclick="this.nextElementSibling.style.display=this.nextElementSibling.style.display===\'none\'?\'block\':\'none\'">' +
                '<span>' + event.icon + '</span>' +
                '<span>' + escapeHtml(event.name) + '</span>' +
                '</div>' +
                '<div class="agent-card-body"></div>';
            currentAiMessage.appendChild(currentAgentCards[event.agent_id]);
            break;
        case 'agent.tool_call':
            if (currentAgentCards[event.agent_id]) {
                var body = currentAgentCards[event.agent_id].querySelector('.agent-card-body');
                body.innerHTML += '<div class="tool-call">🔧 ' +
                    escapeHtml(event.tool) + '(' + escapeHtml(event.model) + ')</div>';
            }
            break;
        case 'agent.tool_result':
            if (currentAgentCards[event.agent_id]) {
                var body2 = currentAgentCards[event.agent_id].querySelector('.agent-card-body');
                body2.innerHTML += '<div class="tool-result">✅ ' +
                    escapeHtml(event.summary) + '</div>';
            }
            break;
        case 'agent.done': break;
        case 'supervisor.conclusion':
            currentAiMessage.innerHTML +=
                '<div style="color:var(--accent);margin-top:8px;font-weight:600">✅ Slutsats:</div>';
            break;
        case 'token':
            currentAiMessage.innerHTML += event.token;
            break;
        case 'done':
            es.close();
            finishStream();
            break;
        case 'error':
            currentAiMessage.innerHTML +=
                '<div style="color:#ff5252;margin-top:8px">❌ ' + escapeHtml(event.message) + '</div>';
            es.close();
            finishStream();
            break;
    }
    scrollBottom();
}

function finishStream() {
    if (currentAiMessage && !currentAiMessage.textContent.trim()) {
        currentAiMessage.innerHTML = '<em style="color:var(--text-muted)">(inget svar)</em>';
    }
    streaming = false;
    document.getElementById('send-btn').disabled = false;
    document.getElementById('prompt-input').focus();
    currentAiMessage = null;
    currentAgentCards = {};
}

function escapeHtml(text) {
    var div = document.createElement('div');
    div.textContent = text;
    return div.innerHTML;
}
//
